/* Candidaturas: interface local, reutiliza navegação e backup do StepByStep. */
(()=>{
  'use strict';
  const A=ApplicationCore,C=StudyCore,E=C.esc;
  db.applications??=[];
  let editing=null,query='',filter='',sort='recent',dueOnly=false;
  const page=document.createElement('section');page.id='applicationPage';page.className='study-page';page.hidden=true;
  page.innerHTML=`<div class="study-top"><div><h1>Candidaturas</h1></div><div class="tools"><button class="primary" id="newApplication">+ Candidatura</button></div></div><div class="app-summary" id="applicationSummary"></div><div class="app-filters"><input id="applicationSearch" aria-label="Buscar candidaturas" placeholder="Buscar empresa, vaga ou observações…"><select id="applicationFilter" aria-label="Filtrar status"><option value="">Todos os status</option>${A.statuses.map(s=>`<option>${E(s)}</option>`).join('')}</select><select id="applicationSort" aria-label="Ordenar candidaturas"><option value="recent">Atualizadas recentemente</option><option value="followup">Próximo acompanhamento</option><option value="company">Empresa A–Z</option></select><label class="music-options" style="margin:0"><input type="checkbox" id="applicationDue"> Acompanhar hoje</label></div><p class="app-count" id="applicationCount"></p><div class="app-grid" id="applicationList"></div><div class="card study-empty" id="applicationEmpty"><h2>Nenhuma candidatura</h2><p hidden></p><button class="primary" id="firstApplication">Adicionar candidatura</button></div>`;
  document.querySelector('footer').before(page);
  const dialog=document.createElement('dialog');dialog.id='applicationDialog';dialog.className='study-dialog';dialog.setAttribute('aria-labelledby','applicationDialogTitle');
  dialog.innerHTML=`<form id="applicationForm"><h2 id="applicationDialogTitle">Nova candidatura</h2><div class="app-form-grid"><div><label for="appCompany">Empresa</label><input id="appCompany" maxlength="150" required></div><div><label for="appRole">Vaga / cargo</label><input id="appRole" maxlength="200" required></div><div><label for="appStatus">Status</label><select id="appStatus">${A.statuses.map(s=>`<option>${E(s)}</option>`).join('')}</select></div><div><label for="appAppliedOn">Data da candidatura (opcional)</label><input id="appAppliedOn" type="date"></div><div class="full"><label for="appURL">Link da vaga (opcional)</label><input id="appURL" type="url" placeholder="https://…" maxlength="2000"></div><div><label for="appLocation">Local / modalidade (opcional)</label><input id="appLocation" placeholder="Ex.: remoto, Campinas, híbrido" maxlength="200"></div><div><label for="appFollowUp">Próximo acompanhamento (opcional)</label><input id="appFollowUp" type="date"></div><div class="full"><label for="appNextAction">Próximo passo (opcional)</label><input id="appNextAction" placeholder="Ex.: adaptar currículo, retornar ao recrutador" maxlength="500"></div><div class="full"><label for="appNotes">Observações</label><textarea id="appNotes" maxlength="20000" placeholder="Requisitos, contatos e o que precisa lembrar."></textarea></div></div><p id="applicationError" class="event-error" role="alert"></p><div class="dialog-buttons"><button type="button" id="cancelApplication">Cancelar</button><button class="primary">Salvar candidatura</button></div></form>`;document.body.appendChild(dialog);
  const removeDialog=document.createElement('dialog');removeDialog.id='applicationDeleteDialog';removeDialog.className='study-dialog';removeDialog.setAttribute('aria-labelledby','applicationDeleteTitle');removeDialog.innerHTML='<h2 id="applicationDeleteTitle">Excluir candidatura?</h2><p id="applicationDeleteDescription" style="margin-top:14px"></p><div class="dialog-buttons"><button id="cancelDeleteApplication">Cancelar</button><button class="danger" id="confirmDeleteApplication">Excluir candidatura</button></div>';document.body.appendChild(removeDialog);
  const notice=document.createElement('div');notice.className='study-toast app-toast';notice.hidden=true;notice.setAttribute('role','status');document.body.appendChild(notice);let noticeTimeout;
  function toast(text){notice.textContent=text;notice.hidden=false;clearTimeout(noticeTimeout);noticeTimeout=setTimeout(()=>notice.hidden=true,4000)}
  function persist(){try{localStorage.setItem(key,JSON.stringify(db));$('saveStatus').textContent='Salvo neste navegador.';return true}catch{toast('Falha ao salvar. Exporte um backup.');return false}}
  function formatDate(d){return d?new Date(d+'T12:00:00').toLocaleDateString('pt-BR'):'Não informada'}
  function isDue(v){return A.active(v.status)&&v.followUp&&v.followUp<=C.dateKey()}
  function render(){
    const items=db.applications||[],active=items.filter(v=>A.active(v.status)).length,interviews=items.filter(v=>['Entrevista','Teste técnico'].includes(v.status)).length,due=items.filter(isDue).length;
    $('applicationSummary').innerHTML=`<div class="study-stats"><div class="study-stat"><strong>${items.length}</strong><span>Candidaturas cadastradas</span></div><div class="study-stat"><strong>${active}</strong><span>Em andamento</span></div><div class="study-stat"><strong>${interviews}</strong><span>Entrevistas / testes</span></div><div class="study-stat"><strong>${due}</strong><span>Acompanhamentos para hoje</span></div></div>`;
    const needle=A.normalize(query);let visible=items.filter(v=>(!filter||v.status===filter)&&(!dueOnly||isDue(v))&&(!needle||A.normalize([v.company,v.role,v.location,v.notes,v.nextAction].join(' ')).includes(needle)));
    visible.sort((a,b)=>sort==='company'?a.company.localeCompare(b.company,'pt-BR'):sort==='followup'?(a.followUp||'9999').localeCompare(b.followUp||'9999'):b.updatedAt.localeCompare(a.updatedAt));
    $('applicationCount').textContent=`${visible.length} de ${items.length} candidatura${items.length===1?'':'s'}`;
    $('applicationList').innerHTML=visible.map(v=>`<article class="application-card"><div class="app-card-top"><div><div class="company">${E(v.company)}</div><h2>${E(v.role)}</h2></div><select data-app-status="${v.id}" aria-label="Status de ${E(v.role)} na ${E(v.company)}">${A.statuses.map(s=>`<option ${v.status===s?'selected':''}>${E(s)}</option>`).join('')}</select></div><div class="app-card-meta">${v.location?`${E(v.location)}<br>`:''}Candidatura: ${formatDate(v.appliedOn)}</div>${v.nextAction||v.followUp?`<div class="app-next ${isDue(v)?'due':''}">${v.followUp?`<strong>${isDue(v)?'Acompanhar: ':'Próximo acompanhamento: '}${formatDate(v.followUp)}</strong>`:''}${v.nextAction?`<div>${E(v.nextAction)}</div>`:''}</div>`:''}${v.notes?`<details class="app-history"><summary>Observações</summary><p style="white-space:pre-wrap;overflow-wrap:anywhere">${E(v.notes)}</p></details>`:''}<details class="app-history"><summary>Histórico de status</summary>${[...v.history].reverse().map(h=>`<p>${new Date(h.at).toLocaleString('pt-BR')} · ${E(h.status)}</p>`).join('')}</details><div class="app-card-footer">${v.url?`<a href="${E(A.safeURL(v.url))}" target="_blank" rel="noopener noreferrer">Abrir vaga</a>`:'<span class="small">Sem link cadastrado</span>'}<div class="buttons"><button data-app-edit="${v.id}">Editar</button><button data-app-delete="${v.id}" aria-label="Excluir ${E(v.role)} na ${E(v.company)}">Excluir</button></div></div></article>`).join('');
    $('applicationEmpty').hidden=visible.length>0;if(items.length&&!visible.length){$('applicationEmpty').querySelector('h2').textContent='Nada encontrado';$('applicationEmpty').querySelector('p').textContent=''}else{$('applicationEmpty').querySelector('h2').textContent='Nenhuma candidatura';$('applicationEmpty').querySelector('p').textContent=''}
  }
  function open(id=null){editing=id;const v=(db.applications||[]).find(v=>v.id===id);$('applicationForm').reset();$('applicationDialogTitle').textContent=v?'Editar candidatura':'Nova candidatura';const fields={appCompany:'company',appRole:'role',appStatus:'status',appAppliedOn:'appliedOn',appURL:'url',appLocation:'location',appFollowUp:'followUp',appNextAction:'nextAction',appNotes:'notes'};for(const [id,k] of Object.entries(fields))$(id).value=v?.[k]||(k==='status'?'A preparar':'');$('applicationError').textContent='';dialog.showModal()}
  $('newApplication').onclick=$('firstApplication').onclick=()=>open();$('cancelApplication').onclick=()=>dialog.close();
  $('applicationForm').onsubmit=e=>{
    e.preventDefault();try{
      const company=$('appCompany').value.trim(),role=$('appRole').value.trim();if(!company||!role)throw Error('Informe empresa e vaga.');
      const current=(db.applications||[]).find(v=>v.id===editing),now=new Date().toISOString(),status=$('appStatus').value;
      const v={id:current?.id||C.uid(),company,role,status,url:A.safeURL($('appURL').value),appliedOn:$('appAppliedOn').value,followUp:$('appFollowUp').value,location:$('appLocation').value.trim(),nextAction:$('appNextAction').value.trim(),notes:$('appNotes').value.trim(),createdAt:current?.createdAt||now,updatedAt:now,history:[...(current?.history||[])]};
      if(!current||current.status!==status)v.history.push({status,at:now});A.validate([v]);const before=db.applications;db.applications=current?before.map(item=>item.id===v.id?v:item):[...before,v];if(!persist()){db.applications=before;return}dialog.close();render();toast('Candidatura salva.');
    }catch(err){$('applicationError').textContent=err.message}
  };
  $('applicationSearch').oninput=()=>{query=$('applicationSearch').value;render()};$('applicationFilter').onchange=()=>{filter=$('applicationFilter').value;render()};$('applicationSort').onchange=()=>{sort=$('applicationSort').value;render()};$('applicationDue').onchange=()=>{dueOnly=$('applicationDue').checked;render()};
  $('applicationList').onchange=e=>{const id=e.target.dataset.appStatus;if(!id)return;const v=db.applications.find(v=>v.id===id),status=e.target.value;if(!v||v.status===status)return;const old={status:v.status,updatedAt:v.updatedAt,history:[...v.history]};v.status=status;v.updatedAt=new Date().toISOString();v.history.push({status,at:v.updatedAt});if(!persist())Object.assign(v,old);render()};
  let deleteId=null;$('applicationList').onclick=e=>{const edit=e.target.closest('[data-app-edit]'),remove=e.target.closest('[data-app-delete]');if(edit)open(edit.dataset.appEdit);if(remove){deleteId=remove.dataset.appDelete;const v=db.applications.find(v=>v.id===deleteId);$('applicationDeleteDescription').textContent=`Excluir “${v.role}” na ${v.company}, incluindo observações e histórico de status?`;removeDialog.showModal()}};
  $('cancelDeleteApplication').onclick=()=>removeDialog.close();$('confirmDeleteApplication').onclick=()=>{const previous=db.applications;db.applications=previous.filter(v=>v.id!==deleteId);if(!persist()){db.applications=previous;return}removeDialog.close();render();toast('Candidatura excluída.')};
  window.Applications={refresh:()=>{if(!page.hidden)render()},setVisible:visible=>{page.hidden=!visible;if(visible)render()}};render();
})();
